package com.aclibrary.library;
import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api/issues") public class IssueController{
 private final IssueRepository repo; private final BookRepository books; private final UserRepository users; IssueController(IssueRepository r,BookRepository b,UserRepository u){repo=r;books=b;users=u;}
 private Map<String,Object> dto(Issue i){Map<String,Object> m=new LinkedHashMap<>();m.put("id",i.getId());m.put("bookId",i.getBook().getId());m.put("bookTitle",i.getBook().getTitle());m.put("studentId",i.getStudent().getId());m.put("studentName",i.getStudent().getName());m.put("issueDate",i.getIssueDate());m.put("dueDate",i.getDueDate());m.put("returnDate",i.getReturnDate());return m;}
 @GetMapping public List<Map<String,Object>> all(){return repo.findAll().stream().map(this::dto).toList();}
 @PostMapping public ResponseEntity<?> create(@RequestBody Map<String,Object> p){try{Book b=books.findById(Long.valueOf(p.get("bookId").toString())).orElseThrow();User u=users.findById(Long.valueOf(p.get("studentId").toString())).orElseThrow();if(b.getAvailableCopies()<1)return ResponseEntity.badRequest().body(Map.of("message","No available copies"));Issue i=new Issue();i.setBook(b);i.setStudent(u);i.setIssueDate(LocalDate.parse(p.get("issueDate").toString()));i.setDueDate(LocalDate.parse(p.get("dueDate").toString()));b.setAvailableCopies(b.getAvailableCopies()-1);books.save(b);return ResponseEntity.ok(dto(repo.save(i)));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("message","Invalid issue details: "+e.getMessage()));}}
 @PutMapping("/{id}") public ResponseEntity<?> update(@PathVariable Long id,@RequestBody Map<String,Object> p){return repo.findById(id).map(i->{if(p.get("returnDate")!=null&&i.getReturnDate()==null){i.setReturnDate(LocalDate.parse(p.get("returnDate").toString()));Book b=i.getBook();b.setAvailableCopies(Math.min(b.getTotalCopies(),b.getAvailableCopies()+1));books.save(b);}return ResponseEntity.ok(dto(repo.save(i)));}).orElse(ResponseEntity.notFound().build());}
 @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){if(!repo.existsById(id))return ResponseEntity.notFound().build();repo.deleteById(id);return ResponseEntity.noContent().build();}
}
